-- Squiggly Circle level tests: continuous closed annular border generated by
-- Lines.generate, real CCD contacts at seams and inflections from both sides
-- of the border and both traversal directions, and closed-line metadata
-- preservation.
--
-- Plain LuaJIT lacks the "?/init.lua" package pattern that LÖVE provides;
-- add it so the level-select preview module can be required here.
local script_dir = debug.getinfo(1, "S").source:match("@(.*)/.*$") or "."
package.path = package.path .. ";" .. script_dir .. "/../?/init.lua"

local H = require("tests.helpers.engine_helpers")
local Ball = require("src.entities.ball")
local Peg = require("src.entities.peg")
local Replay = require("src.systems.replay")
local Config = require("src.config")
local LevelManager = require("src.systems.level_manager")
local Lines = require("src.systems.lines")
local SimulationSnapshot = require("src.systems.simulation_snapshot")
local LevelSelectState = require("src.states.level_select")

local RING_CENTER = { x = 600, y = 950 }
local APPROACH_SPEED = 300
local CROSS_SPEED = 400
local HIGH_SPEED = 1600
-- Seam 1 is the first generated join; seam 19 straddles a curvature sign
-- change of the polar source curve (r^2 + 2r'^2 - r r'' changes sign there).
local SEAM = 1
local INFLECTION_SEAM = 19
local CLOSING_SEAM = 192

local function distance(a, b)
	local dx, dy = b.x - a.x, b.y - a.y
	return math.sqrt(dx * dx + dy * dy)
end

local function fresh_level()
	package.loaded["src.levels.squiggly_circle"] = nil
	return require("src.levels.squiggly_circle")
end

local function new_engine(data)
	local eng = H.new_engine()
	H.setup_engine(eng, data.pegs, data.type_counts, data.level_seed)
	return eng
end

local function launch(eng, x, y, vx, vy)
	local ball = Ball.new(x, y)
	ball.launched = true
	ball.vx, ball.vy = vx, vy
	eng:registerBall(ball)
	eng.active_balls = { ball }
	eng.shot_id = eng.shot_id + 1
	eng.shot_initial_step = eng.sim_step_id + 1
	eng.styleShots:reset_shot()
	eng.ballState:reset_shot()
	eng.slideInversion:reset_shot()
	eng.events:stage("ball_launched", {
		ball_id = ball.id, x = ball.x, y = ball.y, vx = ball.vx, vy = ball.vy,
	})
	return ball
end

-- Step the engine, returning raw peg-contact events and the closest the ball
-- came to the ring center (used to prove it never leaked to the other side).
local function run(eng, ball, steps)
	local events, scored = {}, {}
	local min_center = math.huge
	eng.callbacks.onStepFinalized = function(engine, rec)
		for _, e in ipairs(rec.raw_events) do
			if e.type == "ball_contacted_peg" then events[#events + 1] = e end
		end
		for _, e in ipairs(rec.derived_events) do
			if e.type == "peg_scored" then scored[#scored + 1] = e end
		end
	end
	for _ = 1, steps do
		if eng.is_halted then break end
		eng.sim_step_id = eng.sim_step_id + 1
		eng:savePreviousState()
		eng:stepSimulation(Config.fixed_dt)
		local d = distance(ball, RING_CENTER)
		if d < min_center then min_center = d end
		if eng.shot_end_reason == "__handled" then break end
	end
	return events, min_center, scored
end

-- The authored squiggle traverses increasing polar angle. Determine each
-- entry/exit from that independent ordering, not a nearest-cap search.
local function seam_info(a, b)
	local function mid(u, v)
		return { x = (u.x + v.x) * 0.5, y = (u.y + v.y) * 0.5 }
	end
	local function exit_cap(peg)
		local s = mid(peg.corners[1], peg.corners[2])
		local e = mid(peg.corners[3], peg.corners[4])
		local cross = (s.x - RING_CENTER.x) * (e.y - RING_CENTER.y)
			- (s.y - RING_CENTER.y) * (e.x - RING_CENTER.x)
		return cross > 0 and 2 or 1
	end
	local ca, cb = exit_cap(a), 3 - exit_cap(b)
	local e1, e2 = a.corners[ca * 2 - 1], a.corners[ca * 2]
	local b1, b2 = b.corners[cb * 2 - 1], b.corners[cb * 2]
	local err = math.min(math.max(distance(e1, b1), distance(e2, b2)),
		math.max(distance(e1, b2), distance(e2, b1)))
	assert_true(err <= Lines.CONTACT_TOLERANCE, "ordered exit and entry share both cap endpoints")
	local d1, d2 = distance(e1, a), distance(e2, a)
	local inner, outer = e1, e2
	if d1 > d2 then inner, outer = e2, e1 end
	local nx, ny = outer.x - a.x, outer.y - a.y
	local length = math.sqrt(nx * nx + ny * ny)
	return {
		inner = inner, outer = outer,
		center = mid(inner, outer),
		normal = { x = nx / length, y = ny / length },
		err = err, a_cap = ca, b_cap = cb,
	}
end

local function peg_hits(events)
	local hits = {}
	for _, e in ipairs(events) do hits[e.peg_id] = true end
	return hits
end

-- A ball that grazes along the outer surface of one piece and crosses the
-- shared cap onto its neighbor. Starting from_b runs the reverse traversal.
local function graze_cross(index, from_b, speed, inside)
	local data = fresh_level()
	local pegs = data.pegs
	local a, b = pegs[index], pegs[index % #pegs + 1]
	local info = seam_info(a, b)
	local from = from_b and b or a
	local cap = from_b and info.b_cap or info.a_cap
	local cap_angle = cap == 1 and from.theta_start or from.theta_end_abs
	-- cap 1 is the piece's theta_start: its interior lies at larger angles.
	local interior_sign = cap == 1 and 1 or -1
	local to_seam_sign = -interior_sign
	local da = 6 / from.r_out
	local angle = cap_angle + interior_sign * da
	local radius = inside and (from.r_in - Config.ball_radius - 0.25)
		or (from.r_out + Config.ball_radius + 0.25)
	local x = from.x + radius * math.cos(angle)
	local y = from.y + radius * math.sin(angle)
	local vx = -math.sin(angle) * to_seam_sign * speed
	local vy = math.cos(angle) * to_seam_sign * speed
	local eng = new_engine(data)
	local ball = launch(eng, x, y, vx, vy)
	local events, min_center, scored = run(eng, ball, 40)
	return {
		a = a, b = b, ball = ball, engine = eng, scored = scored,
		hits = peg_hits(events),
		events = events,
		min_center = min_center,
	}
end

-- Direct normal approach at a seam from one side of the border.
local function approach(index, side, speed)
	local data = fresh_level()
	local pegs = data.pegs
	local a, b = pegs[index], pegs[index % #pegs + 1]
	local info = seam_info(a, b)
	local clearance = Config.ball_radius + 4
	local x, y, vx, vy
	if side == "outside" then
		x = info.outer.x + info.normal.x * clearance
		y = info.outer.y + info.normal.y * clearance
		vx, vy = -info.normal.x * speed, -info.normal.y * speed
	else
		x = info.inner.x - info.normal.x * clearance
		y = info.inner.y - info.normal.y * clearance
		vx, vy = info.normal.x * speed, info.normal.y * speed
	end
	local eng = new_engine(data)
	local ball = launch(eng, x, y, vx, vy)
	local before = distance(ball, RING_CENTER)
	local events, min_center = run(eng, ball, 40)
	return {
		a = a, b = b, ball = ball, events = events, min_center = min_center,
		before = before, after = distance(ball, RING_CENTER),
	}
end

local function finite_state(ball)
	for _, value in ipairs({ ball.x, ball.y, ball.vx, ball.vy }) do
		if value ~= value or math.abs(value) == math.huge then return false end
	end
	return true
end

return {
	setup = function()
		LevelManager.virtual_width = 1200
		LevelManager.virtual_height = 1900
		Config.virtual_width = 1200
		Config.virtual_height = 1900
		Config.gravity = 1000
		Config.launch_speed = 800
	end,

	test_level_border_is_a_valid_closed_line = function()
		local data = fresh_level()
		assert_true(#data.pegs >= 192, "the border carries at least two pieces per cubic")
		assert_true(data.type_counts.red + data.type_counts.green <= #data.pegs)
		assert_eq(data.level_seed, 20260918)
		for i, peg in ipairs(data.pegs) do
			assert_eq(peg.shape, "annular")
			assert_true(peg.r_in > 0 and peg.r_out > peg.r_in)
			assert_true(peg.motion == nil, "border pegs stay ordinary static pegs")
			assert_eq(peg.line.id, "squiggly_border")
			assert_eq(peg.line.index, i)
			assert_eq(peg.line.count, #data.pegs)
			assert_true(peg.line.closed)
			assert_eq(peg.line.gap, 0)
		end
		Lines.validate(data.pegs)
		assert_eq(#data.pegs, CLOSING_SEAM, "CCD scenarios target the actual final-to-first seam")
		for i, peg in ipairs(data.pegs) do seam_info(peg, data.pegs[i % #data.pegs + 1]) end
	end,

	test_boundary_filter_keeps_large_radius_border_pieces = function()
		-- Regression: an annular piece's arc center can be far outside the
		-- playfield while the emitted sector stays well inside. The boundary
		-- pass must test the analytic sector, not r_out around the arc center,
		-- or it discards valid pieces and breaks line contiguity.
		local Validator = require("src.systems.level_validator")
		local data = fresh_level()
		local kept = Validator.validate_pegs(data.pegs, {})
		assert_eq(#kept, #data.pegs, "no border piece is discarded")
		Lines.validate(kept)
	end,

	test_boundary_filter_includes_between_vertex_extrema_and_rotation = function()
		local Validator = require("src.systems.level_validator")
		for _, case in ipairs({
			{ 1100.05, 500, 0 }, { 99.95, 500, math.pi }, { 600, 99.95, -math.pi / 2 },
		}) do
			local peg = Peg.new_annular(case[1], case[2], "blue", 80, 100, -0.15, 0.25)
			Peg.set_transform(peg, peg.x, peg.y, case[3])
			for i = 1, #peg.polygon, 2 do
				assert_true(peg.polygon[i] >= 0 and peg.polygon[i] <= 1200 and peg.polygon[i + 1] >= 0,
					"review probe polygon falsely appears in bounds")
			end
			assert_eq(#Validator.validate_pegs({ peg }, {}), 0, "analytic extremum intersects wall")
			local messages, old_print = {}, print
			_G.print = function(message) messages[#messages + 1] = message end
			local ok, err = pcall(Validator.check_initialized_positions, { peg }, {})
			_G.print = old_print
			assert_true(ok, tostring(err))
			assert_eq(#messages, 1, "initialized rotated position warns too")
		end
		local below = Peg.new_annular(600, 2000, "blue", 80, 100, -0.15, 0.25)
		assert_eq(#Validator.validate_pegs({ below }, {}), 1, "floor remains unchecked")
	end,

	test_real_ball_crosses_seams_in_both_traversal_directions = function()
		Config.gravity = 0
		for _, index in ipairs({ SEAM, INFLECTION_SEAM, CLOSING_SEAM }) do
			for _, from_b in ipairs({ false, true }) do
				local result = graze_cross(index, from_b, CROSS_SPEED)
				local direction = from_b and "reverse" or "forward"
				assert_true(result.hits[result.a.original_index] == true,
					"seam " .. index .. " " .. direction .. " scored the first neighbor")
				assert_true(result.hits[result.b.original_index] == true,
					"seam " .. index .. " " .. direction .. " scored the second neighbor")
				assert_true(result.events ~= nil and #result.events >= 2,
					"seam " .. index .. " " .. direction .. " produced real contact events")
				assert_true(Lines.is_intentional_contact(result.a, result.b),
					"seam " .. index .. " " .. direction .. " keeps the shared-boundary contact")
				assert_true(finite_state(result.ball),
					"seam " .. index .. " " .. direction .. " kept a finite ball state")
				-- Sanity: the graze stays near the border instead of being
				-- launched away. Direct high-speed approaches below own the
				-- full no-tunnel proof.
				assert_true(result.min_center > 250,
					"seam " .. index .. " " .. direction .. " stayed near the border")
			end
		end
		Config.gravity = 1000
	end,

	test_border_contact_from_both_sides_at_seams_and_inflections = function()
		Config.gravity = 0
		for _, index in ipairs({ SEAM, INFLECTION_SEAM, CLOSING_SEAM }) do
			for _, side in ipairs({ "outside", "inside" }) do
				local result = approach(index, side, APPROACH_SPEED)
				assert_true(#result.events >= 1,
					"seam " .. index .. " " .. side .. " produced a real contact")
				assert_true(result.a.hit or result.b.hit,
					"seam " .. index .. " " .. side .. " scored a border peg")
				assert_true(finite_state(result.ball),
					"seam " .. index .. " " .. side .. " kept a finite ball state")
				if side == "outside" then
					assert_true(result.after > result.before + 20,
						"seam " .. index .. " outside ball bounced outward")
				else
					assert_true(result.after < result.before - 20,
						"seam " .. index .. " inside ball bounced inward")
				end
			end
		end
		Config.gravity = 1000
	end,

	test_closing_seam_inner_surface_crosses_both_directions = function()
		Config.gravity = 0
		for _, from_b in ipairs({ false, true }) do
			local result = graze_cross(CLOSING_SEAM, from_b, CROSS_SPEED, true)
			assert_true(result.hits[result.a.original_index] and result.hits[result.b.original_index],
				"inside traversal contacts both closing-seam neighbors")
			assert_true(finite_state(result.ball))
		end
		Config.gravity = 1000
	end,

	test_high_speed_contacts_do_not_tunnel = function()
		Config.gravity = 0
		for _, index in ipairs({ SEAM, INFLECTION_SEAM, CLOSING_SEAM }) do
			for _, side in ipairs({ "outside", "inside" }) do
				local result = approach(index, side, HIGH_SPEED)
				assert_true(#result.events >= 1,
					"fast seam " .. index .. " " .. side .. " produced a contact")
				assert_true(finite_state(result.ball),
					"fast seam " .. index .. " " .. side .. " stayed finite")
				if side == "outside" then
					assert_true(result.after >= result.before,
						"fast outside ball did not tunnel through the border")
				else
					assert_true(result.after <= result.before,
						"fast inside ball did not tunnel through the border")
				end
			end
		end
		Config.gravity = 1000
	end,

	test_closed_line_metadata_survives_snapshot = function()
		local data = fresh_level()
		local eng = new_engine(data)
		local snapshot = SimulationSnapshot.capture(eng)
		assert_eq(#snapshot.pegs, #data.pegs)
		for i, peg in ipairs(snapshot.pegs) do
			local source = data.pegs[i]
			assert_eq(peg.original_index, i, "peg identity follows generation order")
			assert_eq(peg.shape, "annular")
			assert_true(peg.r_in > 0)
			assert_true(peg.line ~= nil, "closed-line metadata is captured")
			assert_eq(peg.line.id, source.line.id)
			assert_eq(peg.line.index, i)
			assert_eq(peg.line.count, #data.pegs)
			assert_true(peg.line.closed)
			assert_eq(peg.line.gap, 0)
		end
		-- Snapshot metadata is a by-value copy, not a live reference.
		local first = snapshot.pegs[1]
		data.pegs[1].line.index = 99
		assert_eq(first.line.index, 1)
	end,

	test_shared_boundary_scores_once_and_clears_only_hit_pegs = function()
		Config.gravity = 0
		for _, from_b in ipairs({ false, true }) do
			local result = graze_cross(CLOSING_SEAM, from_b, CROSS_SPEED)
			local eng, scored, weighted = result.engine, {}, 0
			for _, event in ipairs(result.scored) do
				assert_true(not scored[event.peg_id], "repeated cap contacts never score twice")
				scored[event.peg_id] = true
				assert_true(result.hits[event.peg_id], "every score derives from real CCD contact")
				weighted = weighted + event.peg_value * event.multiplier_at_hit
			end
			assert_true(scored[result.a.original_index] and scored[result.b.original_index],
				"both final-to-first neighbors produce derived scores")
			assert_eq(#eng.turnPegsHit, #result.scored)
			assert_eq(eng.hitCounter, #result.scored)
			local score = weighted * #result.scored + eng.bonusScore + eng.styleScore
			assert_eq(eng:getTurnScore(), score)
			local before = #eng.pegs
			-- Finish the controlled shot through the real fall-out/clearing path.
			for _, ball in ipairs(eng.active_balls) do
				ball.x, ball.y, ball.vx, ball.vy = 600, 2200, 0, 100
			end
			local _, _, later_scores = run(eng, result.ball, 180)
			assert_eq(#later_scores, 0)
			assert_true(eng.clearQueue == nil)
			assert_eq(#eng.pegs, before - #result.scored)
			assert_eq(#eng.annular_pegs, #eng.pegs)
			assert_true(eng.peg_by_id[result.a.original_index] == nil)
			assert_true(eng.peg_by_id[result.b.original_index] == nil)
			for _, peg in ipairs(eng.pegs) do
				assert_true(not scored[peg.original_index], "no scored peg survives clearing")
				assert_true(not peg.hit, "unhit border remains intact")
			end
			assert_eq(#eng.turnPegsHit, #result.scored, "clearing preserves scored identities")
			assert_eq(eng:getTurnScore(), score, "clearing preserves the earned score")
		end
		Config.gravity = 1000
	end,

	test_generated_squiggle_replay_continues_real_ccd = function()
		Config.gravity = 0
		local original = new_engine(fresh_level())
		local info = seam_info(original.pegs[CLOSING_SEAM], original.pegs[1])
		local clearance = Config.ball_radius + 12
		local ball = launch(original, info.outer.x + info.normal.x * clearance,
			info.outer.y + info.normal.y * clearance, -info.normal.x * APPROACH_SPEED,
			-info.normal.y * APPROACH_SPEED)
		local contacts = run(original, ball, 1)
		assert_eq(#contacts, 0, "capture an in-flight ball before its first contact")
		local file = "temp/test_squiggly_replay_capture.lua"
		Replay.capture(file, {
			level_name = "squiggly_circle", pegs = original.pegs, balls = original.active_balls,
			bucket = original.bucket, isFever = original.isFever, hitCounter = original.hitCounter,
			redPegsHitAmount = original.redPegsHitAmount, currentMultiplier = original.currentMultiplier,
		})
		local capture = Replay.load(file)
		assert_true(capture ~= nil)
		local resumed = new_engine(fresh_level())
		local owned_pegs = {}
		for i, peg in ipairs(resumed.pegs) do owned_pegs[i] = peg end
		resumed:applyReplayState(capture)
		resumed.sim_step_id = original.sim_step_id
		assert_eq(resumed.active_balls[1].id, ball.id)
		for i, peg in ipairs(resumed.pegs) do
			assert_eq(peg, owned_pegs[i], "restoration retains level-owned geometry")
			assert_eq(peg.original_index, i)
			for _, field in ipairs({ "id", "index", "count", "closed", "gap" }) do
				assert_eq(capture.pegs[i].line[field], original.pegs[i].line[field])
				assert_eq(peg.line[field], original.pegs[i].line[field])
			end
		end
		Lines.validate(resumed.pegs)
		local first_steps, resumed_steps = H.make_recorder(original), H.make_recorder(resumed)
		for _ = 1, 40 do
			for _, engine in ipairs({ original, resumed }) do
				engine.sim_step_id = engine.sim_step_id + 1
				engine:savePreviousState()
				engine:stepSimulation(Config.fixed_dt)
			end
			assert_eq(#resumed.active_balls, #original.active_balls)
			for i, source in ipairs(original.active_balls) do
				for _, field in ipairs({ "id", "x", "y", "vx", "vy" }) do
					assert_eq(resumed.active_balls[i][field], source[field], "continued ball " .. field)
				end
			end
			assert_eq(resumed:getTurnScore(), original:getTurnScore())
			for i, peg in ipairs(original.pegs) do
				assert_eq(resumed.pegs[i].original_index, peg.original_index)
				assert_eq(resumed.pegs[i].hit, peg.hit)
			end
		end
		local count = 0
		local function compare(actual, expected, context)
			if type(expected) ~= "table" then assert_eq(actual, expected, context); return end
			assert_eq(type(actual), "table", context)
			for key, value in pairs(expected) do compare(actual[key], value, context .. "." .. key) end
			for key in pairs(actual) do assert_true(expected[key] ~= nil, context .. " extra field " .. key) end
		end
		for i, record in ipairs(first_steps) do
			for _, phase in ipairs({ "raw_events", "derived_events" }) do
				assert_eq(#resumed_steps[i][phase], #record[phase])
				for j, event in ipairs(record[phase]) do
					compare(resumed_steps[i][phase][j], event, "continued event")
					if event.type == "ball_contacted_peg" then count = count + 1 end
				end
			end
		end
		assert_true(count > 0, "restored ball contacts actual generated annular geometry")
		Config.gravity = 1000
	end,

	test_preview_pegs_match_generated_border = function()
		local data = fresh_level()
		local state = setmetatable({}, { __index = LevelSelectState })
		state:_build_preview_pegs(data)
		assert_true(state.preview_pegs ~= nil)
		assert_eq(#state.preview_pegs, #data.pegs)
		for i, peg in ipairs(state.preview_pegs) do
			assert_eq(peg.x, data.pegs[i].x)
			assert_eq(peg.y, data.pegs[i].y)
			assert_eq(peg.r_in, data.pegs[i].r_in)
			assert_eq(peg.r_out, data.pegs[i].r_out)
			assert_eq(peg.line.id, "squiggly_border")
			assert_eq(peg.line.index, i)
		end
	end,
}
